// Dependency-free real-browser interaction tests. Artifacts stay in system temp.
// Run: node browser-learning-tests.cjs
const {spawn}=require('node:child_process');
const fs=require('node:fs');
const os=require('node:os');
const path=require('node:path');
const {pathToFileURL}=require('node:url');
const http=require('node:http');
const profile=fs.mkdtempSync(path.join(os.tmpdir(),'sqlflow-learning-browser-'));
const artifacts=fs.mkdtempSync(path.join(os.tmpdir(),'sqlflow-learning-artifacts-'));
const chromePath=process.env.SQLFLOW_CHROME || 'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe';
let url=process.env.SQLFLOW_TEST_URL||pathToFileURL(path.join(__dirname,'index.html')).href,chrome=null,previewServer=null;
if(process.argv.includes('--regression'))url=pathToFileURL(path.join(__dirname,'tests.html')).href;
async function startBrowser(){if(process.argv.includes('--http')){previewServer=http.createServer((request,response)=>{try{const requested=decodeURIComponent(new URL(request.url,'http://localhost').pathname),parts=requested.split('/');if(parts.some(part=>part.startsWith('.'))){response.writeHead(403);response.end('Forbidden');return;}const file=path.resolve(__dirname,'.'+(requested==='/'?'/index.html':requested)),types={'.html':'text/html','.js':'text/javascript','.css':'text/css','.jpeg':'image/jpeg','.jpg':'image/jpeg','.png':'image/png'};const type=types[path.extname(file)];if(!file.startsWith(__dirname+path.sep)||!type){response.writeHead(403);response.end('Forbidden');return;}fs.readFile(file,(error,content)=>{response.writeHead(error?404:200,{'Content-Type':type});response.end(error?'Not found':content);});}catch(_){response.writeHead(400);response.end('Bad request');}});await new Promise(resolve=>previewServer.listen(0,'127.0.0.1',resolve));url='http://127.0.0.1:'+previewServer.address().port+'/';}chrome=spawn(chromePath,['--headless=new','--disable-gpu','--no-sandbox','--no-first-run','--disable-extensions','--remote-debugging-port=0','--window-size=1366,1000','--user-data-dir='+profile,url],{stdio:['ignore','ignore','pipe'],windowsHide:true});let chromeErrors='';chrome.stderr.on('data',chunk=>{chromeErrors=(chromeErrors+chunk.toString()).slice(-4000);});chrome.on('exit',(code,signal)=>{if(code||signal)console.error('Chrome exited:',code,signal,chromeErrors);});}
let socket,sequence=0;const pending=new Map(),errors=[],checks=[],captures=[];let videoAttempt=null;
const pause=ms=>new Promise(resolve=>setTimeout(resolve,ms));
function assert(value,message){if(!value)throw new Error(message);checks.push(message);if(checks.length%25===0)console.error('PROGRESS '+checks.length+' checks: '+message);}
function send(method,params={}){return new Promise((resolve,reject)=>{const id=++sequence;const timeout=setTimeout(()=>{pending.delete(id);reject(new Error('Chrome command timed out: '+method));},20000);pending.set(id,{resolve:value=>{clearTimeout(timeout);resolve(value);},reject:error=>{clearTimeout(timeout);reject(error);}});socket.send(JSON.stringify({id,method,params}));});}
async function evaluate(expression){const response=await send('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true});if(response.exceptionDetails)throw new Error(JSON.stringify(response.exceptionDetails));return response.result.value;}
async function connect(){let port;for(let attempt=0;attempt<100;attempt++){try{port=fs.readFileSync(path.join(profile,'DevToolsActivePort'),'utf8').split('\n')[0];break;}catch(_){}await pause(100);}if(!port)throw new Error('Chrome did not start. Set SQLFLOW_CHROME if Chrome is elsewhere.');const pages=await(await fetch('http://127.0.0.1:'+port+'/json/list')).json();const page=pages.find(item=>item.type==='page');socket=new WebSocket(page.webSocketDebuggerUrl);await new Promise((resolve,reject)=>{socket.addEventListener('open',resolve,{once:true});socket.addEventListener('error',reject,{once:true});});socket.addEventListener('message',event=>{const message=JSON.parse(event.data);if(message.method==='Runtime.exceptionThrown'||message.method==='Log.entryAdded'&&message.params.entry.level==='error')errors.push(message);if(message.id&&pending.has(message.id)){const p=pending.get(message.id);pending.delete(message.id);message.error?p.reject(new Error(message.error.message)):p.resolve(message.result);}});socket.addEventListener('close',event=>console.error('Chrome debugging socket closed:',event.code));socket.addEventListener('error',event=>console.error('Chrome debugging socket error:',event.message||event.type));await send('Runtime.enable');await send('Log.enable');await send('Page.enable');await send('Browser.setDownloadBehavior',{behavior:'allow',downloadPath:artifacts});}
async function ready(){for(let i=0;i<100;i++){if(await evaluate('!!window.SqlFlow?.academic?.getReport?.()'))return;await pause(100);}throw new Error('App failed to initialize.');}
async function click(selector){const box=await evaluate(`(()=>{const e=document.querySelector(${JSON.stringify(selector)});if(!e)return null;e.scrollIntoView({block:'center'});const r=e.getBoundingClientRect();return{x:r.left+r.width/2,y:r.top+r.height/2,w:r.width,h:r.height,disabled:e.disabled};})()`);if(!box||!box.w||!box.h||box.disabled)throw new Error('Not visibly clickable: '+selector);try{await send('Input.dispatchMouseEvent',{type:'mousePressed',x:box.x,y:box.y,button:'left',clickCount:1});await send('Input.dispatchMouseEvent',{type:'mouseReleased',x:box.x,y:box.y,button:'left',clickCount:1});}catch(error){throw new Error(selector+': '+error.message);}await pause(40);}
async function button(text,scope='document'){await evaluate(`(()=>{document.querySelectorAll('[data-audit-target]').forEach(e=>e.removeAttribute('data-audit-target'));const root=${scope};const b=Array.from(root.querySelectorAll('button')).find(e=>e.textContent.trim()===${JSON.stringify(text)});if(!b)throw new Error('Button missing: '+${JSON.stringify(text)});b.dataset.auditTarget='true';})()`);await click('[data-audit-target]');}
async function screenshot(name){const picture=await send('Page.captureScreenshot',{format:'png'});fs.writeFileSync(path.join(artifacts,name+'.png'),Buffer.from(picture.data,'base64'));captures.push({name,file:name+'.png',state:await evaluate('({section:document.getElementById("academicTitle").textContent,stage:SqlFlow.visualizer.state.executionResult?.stages[SqlFlow.visualizer.state.currentStep]?.label,tab:SqlFlow.visualizer.state.activeTab,action:SqlFlow.simulation.getPlayer()?.state()})')});if(process.argv.includes('--audit')&&/^(0[1-9]|1[0-7])b?-/.test(name)){console.log('CAPTURE_READY '+path.join(artifacts,name+'.png'));if(process.argv.includes('--pause-on-capture'))await Promise.race([new Promise(resolve=>process.stdin.once('data',resolve)),pause(15000)]);}}
async function run(sql){await evaluate(`document.getElementById('sqlEditor').value=${JSON.stringify(sql)}`);await click('#runQueryBtn');assert(await evaluate('!!SqlFlow.academic.getReport()'),'Run SQL: '+sql);}
async function answer(q){
  if(['sql','repair','fill'].includes(q.type)){const value=q.type==='fill'?q.correct[0]:q.sql;await click('.quiz-answer textarea, .quiz-answer input');await evaluate("document.querySelector('.quiz-answer textarea, .quiz-answer input').value=''");await send('Input.insertText',{text:value});}
  else if(q.type==='order'){for(let target=0;target<q.correct.length;target++){let current=await evaluate(`Array.from(document.querySelectorAll('.quiz-answer li')).findIndex(e=>e.firstChild.textContent.trim()===${JSON.stringify(q.correct[target])})`);while(current>target){await click('.quiz-answer li:nth-child('+(current+1)+') button:first-of-type');current--;}}await button('Use This Order');}
  else if(q.type==='decision'){for(let index=0;index<q.correct.length;index++){await click('.quiz-answer fieldset:nth-of-type('+(index+1)+') input[type="radio"]:nth-of-type(1)'.replace(' input[type="radio"]:nth-of-type(1)', ' label:nth-of-type('+(q.correct[index]?1:2)+') input'));}}
  else{if(q.candidates&&q.correct.length===0){await button('Use Empty Result');return;}for(const index of q.correct)await click('.quiz-answer input[data-option-index="'+index+'"]');}
}
function wrongAnswer(q){const wrong=JSON.parse(JSON.stringify(q));if(['sql','repair'].includes(q.type))wrong.sql='SELECT unknown_column FROM missing_fixture;';else if(q.type==='fill')wrong.correct=['UNSUPPORTED'];else if(q.type==='decision')wrong.correct=q.correct.map(value=>!value);else if(q.type==='order')wrong.correct=q.correct.slice().reverse();else{const count=(q.candidates||q.choices).length,other=Array.from({length:count},(_,index)=>index).find(index=>!q.correct.includes(index));wrong.correct=other!==undefined?[other]:q.correct.slice(0,-1);}return wrong;}
async function activeQuestion(){return evaluate('SqlFlow.quizEngine.question(SqlFlow.quiz.getData().attempt.ids[SqlFlow.quiz.getData().attempt.index])');}
async function selectSetting(id,value){await evaluate(`document.getElementById(${JSON.stringify(id)}).value=${JSON.stringify(String(value))};document.getElementById(${JSON.stringify(id)}).dispatchEvent(new Event('change',{bubbles:true}))`);}
async function topicAttempt(topic,difficulty,mistake){await click('[data-academic-section="quiz"]');await selectSetting('quizTopic',topic);await selectSetting('quizDifficulty',difficulty);await selectSetting('quizCount','5');await selectSetting('quizMode','practice');await click('#quizStart');const count=await evaluate('SqlFlow.quiz.getData().attempt.ids.length');assert(count===5,'Native topic/difficulty selection supplies five questions: '+topic+' '+difficulty);for(let index=0;index<count;index++){const q=await activeQuestion();await answer(index===0&&mistake?wrongAnswer(q):q);await button('Check Answer','document.getElementById("quizSection")');assert(await evaluate('!!document.querySelector("#quizSection .quiz-feedback.'+(index===0&&mistake?'incorrect':'correct')+'")'),'Visible answer feedback: '+topic+' '+difficulty+' '+(index+1));if(index<count-1)await button('Next Question');}await button('Submit Attempt');assert(await evaluate('document.querySelector(".quiz-score").textContent.includes("'+(mistake?'80%':'100%')+'")'),'Deterministic completed topic score: '+topic+' '+difficulty);}
async function studentJourney(){
  await evaluate('window.__confirmCalls=[];window.confirm=message=>{window.__confirmCalls.push(message);return true;}');
  await screenshot('01-open-sqlflow');assert(await evaluate('document.querySelector(".learning-path").textContent.includes("Learn a concept")'),'First-time introduction explains Learn → Visualize → Practice → Review');await screenshot('02-understand-the-path');
  await click('[data-academic-section="learn"]');await evaluate("document.querySelectorAll('[data-lesson-index]')[1].scrollIntoView({block:'center'})");await screenshot('03-study-where');
  await click('[data-lesson-index="1"] button');assert(await evaluate('document.getElementById("sqlEditor").value.includes("WHERE cgpa > 8")'),'Learn WHERE loads a supported real example');assert(await evaluate('document.getElementById("exampleQueries").selectedOptions[0].textContent==="Custom / lesson query"'),'Lesson query is visibly identified as custom in the example selector');await screenshot('04-load-where-example');await click('#runQueryBtn');await screenshot('05-run-where-query');await click('[data-execution-stage="1"]');
  await click('#simulationPlay');await pause(900);await click('#simulationPause');assert(await evaluate('document.querySelector(".simulation-operation").textContent.includes("WHERE")&&document.querySelector(".simulation-predicate-value").textContent.includes("cgpa")'),'WHERE playback exposes actual predicate operands');await screenshot('06-play-and-inspect-where');
  await click('[data-academic-section="help"]');await screenshot('07-interactive-help');await click('[data-tutorial="where"]');const tutorial=await evaluate('SqlFlow.help.tutorials.find(t=>t.id==="where")');for(let index=0;index<tutorial.steps.length;index++){if(tutorial.steps[index][2]==='click')await click(tutorial.steps[index][0]);await button(index===tutorial.steps.length-1?'Finish':'Next','document.querySelector(".walkthrough-card")');}assert(await evaluate('SqlFlow.help.completed().includes("where")'),'First-time WHERE tutorial completes observed actions');await screenshot('08-complete-guided-tutorial');
  await topicAttempt('where','beginner',true);await screenshot('09-topic-quiz-completed');await button('Review Answers');assert(await evaluate('!!document.querySelector(".quiz-feedback.incorrect")'),'Student can review the deliberate mistake');await screenshot('10-review-mistake');await button('Review Lesson','document.querySelector(".quiz-feedback")');assert(await evaluate('!document.getElementById("learnSection").classList.contains("hidden")'),'Mistake review returns to the related Learn lesson');await screenshot('11-return-to-learn');
  await evaluate("document.querySelectorAll('[data-lesson-index]')[3].scrollIntoView({block:'center'})");await screenshot('12-study-inner-join');await click('[data-lesson-index="3"] a[href="#joinVideoLesson"]');await pause(2500);await screenshot('13-selected-neso-video');videoAttempt=await evaluate('({src:document.querySelector(".responsive-video iframe").src,title:document.querySelector(".responsive-video iframe").title,fallback:document.querySelector(".join-video-lesson a").href})');await click('.responsive-video iframe');await pause(1500);await screenshot('13b-video-playback-attempt');
  await click('[data-join-learning="lab"]');const stageIndex=await evaluate('SqlFlow.visualizer.state.executionResult.stages.findIndex(s=>s.joinDetails)');await click('[data-execution-stage="'+stageIndex+'"]');await click('#simulationNext');assert(await evaluate('document.querySelector(".simulation-current").textContent.includes("input row")'),'Learn video links to an actual JOIN simulation');await screenshot('14-run-join-simulation');
  await topicAttempt('inner','intermediate',false);await screenshot('15-complete-join-quiz');await click('#closeAcademicBtn');await click('#downloadReportBtn');await screenshot('16-open-execution-report');await click('#downloadTxtBtn');await evaluate('window.__prints=0;window.print=()=>window.__prints++');await click('#printReportBtn');assert(await evaluate('window.__prints===1'),'Student journey reaches the real Print action');await screenshot('17-export-report');await click('#closeReportBtn');
}
async function refinementChecks(){
  await click('[data-academic-section="quiz"]');const representatives=await evaluate('SqlFlow.quizBank.topics.flatMap(topic=>["beginner","intermediate","advanced"].map(level=>SqlFlow.quizBank.questions.find(q=>q.topic===topic.id&&q.difficulty===level&&q.id.includes("-x"))||SqlFlow.quizBank.questions.find(q=>q.topic===topic.id&&q.difficulty===level)))');
  for(const q of representatives){await evaluate(`SqlFlow.quiz.begin({ids:[${JSON.stringify(q.id)}],count:1,mode:'practice',seed:19})`);await button('Show Hint');assert(await evaluate('document.querySelector(".quiz-hint").textContent.length>8'),'Practice hint is functional: '+q.id);await answer(q);await button('Check Answer');assert(await evaluate('!!document.querySelector(".quiz-feedback.correct")'),'B/I/A browser key: '+q.topic+' '+q.difficulty+' '+q.id);}
  for(const qid of ['basics-x03','projection-x04','multiple-x09','transactions-x10']){const q=await evaluate('SqlFlow.quizEngine.question('+JSON.stringify(qid)+')');await evaluate(`SqlFlow.quiz.begin({ids:[${JSON.stringify(qid)}],count:1,mode:'practice'})`);await answer(q);await button('Check Answer');assert(await evaluate('!!document.querySelector(".quiz-feedback.correct")'),'Expanded edge-case control works: '+qid);}
  await click('#closeAcademicBtn');const sql='SELECT DISTINCT year, COUNT(*) FROM students WHERE cgpa > 8 GROUP BY year HAVING COUNT(*) >= 2 ORDER BY year DESC LIMIT 2;';await run(sql);const stages=await evaluate('SqlFlow.visualizer.state.executionResult.stages.map((s,index)=>({label:s.label,index,actions:s.simulation.actions.length,rows:s.rows}))');
  for(const stage of stages){await click('[data-execution-stage="'+stage.index+'"]');for(let cycle=0;cycle<3;cycle++){await click('#simulationRestart');await click('#simulationPlay');await click('#simulationPause');await click('#simulationRestart');await click('#simulationFinal');assert(await evaluate('SqlFlow.simulation.getPlayer().state().cursor==='+stage.actions+'&&!SqlFlow.simulation.getPlayer().state().playing'),'Repeat play/pause/restart/skip: '+stage.label+' '+cycle);}assert(await evaluate('JSON.stringify(SqlFlow.simulation.snapshot(SqlFlow.visualizer.state.executionResult.stages['+stage.index+'],SqlFlow.simulation.getPlayer().state().cursor).rows)==='+JSON.stringify(JSON.stringify(stage.rows))),'Actual multi-stage replay output: '+stage.label);await screenshot('refined-stage-'+stage.index);}
  await run('SELECT s.student_id, e.grade FROM students s LEFT JOIN enrollments e ON e.student_id = s.student_id;');await click('[data-execution-stage="1"]');await click('#simulationNext');assert(await evaluate('document.querySelector(".simulation-predicate-value").textContent.includes("s.student_id")'),'Reversed ON operands retain source identity');await screenshot('refined-join-pair');await click('#simulationPlay');await click('[data-execution-stage="0"]');await pause(800);assert(await evaluate('SqlFlow.simulation.getPlayer().state().cursor===0&&!SqlFlow.simulation.getPlayer().state().playing'),'Rapid stage switching invalidates pending callbacks');
  await click('#presentationModeBtn');await click('[data-execution-stage="1"]');await click('#simulationNext');assert(await evaluate('parseFloat(getComputedStyle(document.querySelector("#simulationContainer h3")).fontSize)>26'),'Presentation stage title is enlarged');await screenshot('presentation-join');await click('#presentationModeBtn');
  await click('[data-academic-section="help"]');const topics=await evaluate('SqlFlow.help.topics');for(const topic of topics){console.log('HELP_CHECK '+topic.id);await evaluate('SqlFlow.help.openTopic('+JSON.stringify(topic.id)+')');if(topic.sql){await click('#helpDetail summary');await button('Try It Now','document.getElementById("helpDetail")');assert(await evaluate('!!SqlFlow.academic.getReport()'),'Every Help example runs: '+topic.id);await click('[data-academic-section="help"]');await evaluate('SqlFlow.help.openTopic('+JSON.stringify(topic.id)+')');}await button('Review related lesson','document.getElementById("helpDetail")');assert(await evaluate('!document.getElementById("learnSection").classList.contains("hidden")'),'Every Help lesson link works: '+topic.id);await click('[data-academic-section="help"]');await evaluate('SqlFlow.help.openTopic('+JSON.stringify(topic.id)+')');await button('Practice related topic','document.getElementById("helpDetail")');assert(await evaluate('!document.getElementById("quizSection").classList.contains("hidden")'),'Every Help quiz link works: '+topic.id);await click('[data-academic-section="help"]');}
  console.log('HELP_CHECK search and close');await evaluate('document.getElementById("helpSearch").value="row-by-row";document.getElementById("helpSearch").dispatchEvent(new Event("input",{bubbles:true}))');assert(await evaluate('document.querySelector("#helpDetail h3").textContent==="Animation Controls"'),'Help multi-word alias search opens a relevant topic');await click('#closeAcademicBtn');console.log('HELP_CHECK finished');
  for(const invalid of ['',"SELECT name FROM students WHERE city = 'unterminated;",'SELECT bogus FROM students;']){console.log('INVALID_CHECK '+invalid);await evaluate('document.getElementById("sqlEditor").value='+JSON.stringify(invalid));await click('#runQueryBtn');assert(await evaluate('SqlFlow.academic.getReport()===null&&SqlFlow.visualizer.state.executionResult===null'),'Malformed/empty input clears stale results: '+invalid);}
  await run('SELECT name FROM students WHERE city = '+JSON.stringify('x'.repeat(2500))+';');assert(await evaluate('SqlFlow.academic.getReport().output.rowCount===0'),'Long quoted SQL stays valid and empty-result headers survive');
  console.log('INJECTION_CHECK open');await click('[data-academic-section="quiz"]');await evaluate("window.confirm=()=>true;SqlFlow.quiz.begin({ids:['projection-05'],mode:'test',count:1});document.querySelector('.quiz-answer textarea').value='<img src=x onerror=alert(1)>';document.querySelector('.quiz-answer textarea').dispatchEvent(new Event('input',{bubbles:true}))");console.log('INJECTION_CHECK submit');await button('Submit Attempt');console.log('INJECTION_CHECK review');await button('Review Answers');assert(await evaluate('!document.querySelector("#quizSection img")&&!!document.querySelector(".quiz-feedback.incorrect")'),'Hostile SQL remains inert throughout grading and review');await click('#closeAcademicBtn');
}
