  assert(await evaluate('document.querySelector(".responsive-video iframe").src.includes("h4EQBAzW3m4")&&document.querySelector(".join-video-lesson a").href==="https://youtu.be/h4EQBAzW3m4?si=1JtslSqT4QU3ZziA"'),'Requested JOIN video link exists');
