let suiteTimer;
Promise.race([main(),new Promise((_,reject)=>{suiteTimer=setTimeout(()=>reject(new Error('Full Chrome suite exceeded its 8-minute safety limit')),480000);})]).catch(async error=>{console.error(error.stack||error);if(socket){try{const picture=await send('Page.captureScreenshot',{format:'png'}),target=path.join(artifacts,'failure-'+Date.now()+'.png');fs.writeFileSync(target,Buffer.from(picture.data,'base64'));console.error('Failure screenshot: '+target);}catch(captureError){console.error('Failure screenshot unavailable: '+captureError.message);}}console.error(JSON.stringify({passed:checks.length,errors,artifacts,debug:socket?await evaluate('({quiz:SqlFlow.quiz.getData().attempt,stage:SqlFlow.visualizer.state.currentStep,playback:SqlFlow.simulation.getPlayer()?.state()})').catch(()=>null):null},null,2));process.exitCode=1;}).finally(()=>{clearTimeout(suiteTimer);if(socket)socket.close();if(chrome)chrome.kill();if(previewServer){previewServer.closeAllConnections();previewServer.close();}});
